var _rpState={status:'open',rows:[],focus:null};function _escR(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');}
function _rpWhen(iso){if(!iso)return'';try{return new Date(iso).toLocaleString('en-GB',{timeZone:'Asia/Dubai',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});}catch(e){return String(iso);}}
function _rpAgo(iso){if(!iso)return'';var s=(Date.now()-new Date(iso).getTime())/1000;if(s<3600)return Math.max(1,Math.floor(s/60))+'m ago';if(s<86400)return Math.floor(s/3600)+'h ago';return Math.floor(s/86400)+'d ago';}
function _rpSafeUrl(u){return/^https?:\/\//i.test(String(u||''))?String(u):'';}
function updateReportsBadge(n){var b=document.getElementById('rpNavBadge');if(!b)return;if(n>0){b.textContent=n>99?'99+':String(n);b.style.display='inline-block';}
else b.style.display='none';}
function refreshReportsBadge(){if(typeof getToken!=='function'||!getToken())return;fetch(ATP_API+'/admin/reports?status=open',{headers:{Authorization:'Bearer '+getToken()}}).then(function(r){return r.ok?r.json():null;}).then(function(d){if(d&&d.counts)updateReportsBadge(d.counts.open||0);}).catch(function(){});}
function openReportFromFounder(id){_rpState.focus=id||null;_rpState.status='open';showAdminSection('reports',document.querySelector('.admin-nav-item[data-args=\'["reports"]\']'));loadReportsSection();}
function reportsFilter(status){_rpState.status=status;loadReportsSection();}
function loadReportsSection(){var host=document.getElementById('reportsBody');if(!host)return;host.innerHTML='<div style="padding:30px;color:#555;text-align:center">Loading reports…</div>';fetch(ATP_API+'/admin/reports?status='+encodeURIComponent(_rpState.status),{headers:{Authorization:'Bearer '+getToken()}}).then(function(r){return r.json().then(function(j){if(!r.ok)throw new Error(j.error||('HTTP '+r.status));return j;});}).then(function(d){_rpState.rows=d.reports||[];updateReportsBadge((d.counts&&d.counts.open)||0);_renderReports(d.counts||{});}).catch(function(e){host.innerHTML='<div style="padding:30px;color:#f87171;text-align:center">Failed to load reports: '+_escR(e.message||e)+'</div>';});}
var _RP_TYPE={post:'Post',comment:'Comment',member:'Member',message:'Message'};var _RP_RES={removed:['🗑 Removed','#f87171'],dismissed:['✓ Dismissed','#A8FF00'],actioned:['✓ Done','#A8FF00']};function _rpMedia(media){var list=media;if(typeof list==='string'){try{list=JSON.parse(list);}catch(e){list=[];}}
if(!Array.isArray(list)||!list.length)return'';return'<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:10px">'+list.map(function(m){var url=_rpSafeUrl(m&&(m.src||m.url||m.uri));if(!url)return'';var thumb=_rpSafeUrl(m.thumbnail||m.poster)||url;if(/^video/i.test(m.type||'')||/\.(mp4|mov|m4v|webm)(\?|$)/i.test(url)){return'<a href="'+_escR(url)+'" target="_blank" rel="noopener" style="display:flex;align-items:center;justify-content:center;width:120px;height:120px;border-radius:8px;background:#1a1a1a;border:1px solid #2a2a2a;color:#A8FF00;font-size:12px;text-decoration:none">▶ Watch video</a>';}
return'<a href="'+_escR(url)+'" target="_blank" rel="noopener" title="Open full size"><img src="'+_escR(thumb)+'" alt="Reported photo" loading="lazy" style="width:120px;height:120px;object-fit:cover;border-radius:8px;border:1px solid #2a2a2a;display:block"></a>';}).join('')+'</div>';}
function _rpContent(r){var t=r.target;if(!t)return'<div style="color:#888;font-style:italic">This '+_escR((_RP_TYPE[r.target_type]||'item').toLowerCase())+' no longer exists.</div>';var author='<div style="display:flex;align-items:center;gap:10px;margin-bottom:10px">'+
(_rpSafeUrl(t.author_avatar)?'<img src="'+_escR(t.author_avatar)+'" alt="" style="width:32px;height:32px;border-radius:50%;object-fit:cover">':'<div style="width:32px;height:32px;border-radius:50%;background:#222"></div>')+'<div style="flex:1;min-width:0"><div style="color:#fff;font-weight:700">'+_escR(t.author_name||'Member')+
(t.author_banned?' <span style="color:#f87171;font-size:10px;font-weight:800;letter-spacing:.06em">BANNED</span>':'')+'</div>'+'<div style="color:#666;font-size:11px">'+_escR([t.author_number,t.author_email].filter(Boolean).join(' · '))+'</div></div>'+
(t.author_id?'<button class="admin-btn" onclick="openMemberDetail(\''+_escR(t.author_id)+'\')" style="font-size:11px;padding:5px 10px">View member</button>':'')+'</div>';if(r.target_type==='member')return author;var removed=t.is_deleted?'<div style="display:inline-block;margin-bottom:8px;font-size:10px;font-weight:800;letter-spacing:.06em;color:#f87171;border:1px solid rgba(248,113,113,.4);border-radius:4px;padding:2px 6px">ALREADY REMOVED</div>':'';var onPost=r.target_type==='comment'&&t.post_content!=null?'<div style="margin-top:10px;padding:8px 10px;border-left:3px solid #333;color:#888;font-size:12px">On the post: '+_escR(t.post_content)+'</div>':'';return author+removed+'<div style="color:#ddd;font-size:14px;line-height:1.55;white-space:pre-wrap;word-break:break-word">'+(t.content?_escR(t.content):'<span style="color:#666;font-style:italic">(no text)</span>')+'</div>'+
_rpMedia(t.media)+onPost+
(t.created_at?'<div style="color:#555;font-size:11px;margin-top:8px">Posted '+_rpWhen(t.created_at)+'</div>':'');}
function _renderReports(counts){var host=document.getElementById('reportsBody');var tabs=[['open','Open'],['resolved','Closed']];var html='<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px">'+tabs.map(function(t){var on=_rpState.status===t[0];return'<button class="admin-btn" onclick="reportsFilter(\''+t[0]+'\')" style="font-size:12px;padding:6px 14px;'+
(on?'background:rgba(168,255,0,.12);color:#A8FF00;border:1px solid rgba(168,255,0,.35)':'')+'">'+t[1]+' ('+(counts[t[0]]||0)+')</button>';}).join('')+'</div>';if(!_rpState.rows.length){host.innerHTML=html+'<div style="padding:50px 20px;text-align:center;color:#666;border:1px dashed #222;border-radius:12px">'+
(_rpState.status==='open'?'✓ No open reports — the community is healthy.':'No closed reports yet.')+'</div>';return;}
html+=_rpState.rows.map(function(r){var open=!r.resolved;var reporter=((r.reporter_first||'')+' '+(r.reporter_last||'')).trim()||'A member';var canRemove=(r.target_type==='post'||r.target_type==='comment')&&r.target&&!r.target.is_deleted;var t=r.target||{};var res=_RP_RES[r.resolution]||['✓ Closed','#A8FF00'];return'<div id="rp-'+_escR(r.id)+'" data-rp="'+_escR(r.id)+'" style="background:#0d0d0d;border:1px solid #1f1f1f;border-radius:12px;padding:16px;margin-bottom:12px">'+'<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:6px">'+'<span style="background:#333;color:#fff;font-size:10px;font-weight:700;padding:2px 7px;border-radius:4px;text-transform:uppercase">'+_escR(_RP_TYPE[r.target_type]||r.target_type)+'</span>'+'<strong style="color:#fff;font-size:14px">'+_escR(r.reason)+'</strong>'+
(r.reports_on_target>1?'<span style="color:#f59e0b;font-size:11px;font-weight:700">'+r.reports_on_target+' reports on this '+_escR((_RP_TYPE[r.target_type]||'item').toLowerCase())+'</span>':'')+'</div>'+'<div style="color:#888;font-size:12px">Reported by <span style="color:#ccc">'+_escR(reporter)+'</span> · '+_rpWhen(r.created_at)+' ('+_rpAgo(r.created_at)+')</div>'+
(r.description?'<div style="margin-top:8px;color:#ccc;font-size:13px;font-style:italic">“'+_escR(r.description)+'”</div>':'')+'<div style="margin-top:12px;padding:14px;background:#141414;border:1px solid #222;border-radius:10px">'+_rpContent(r)+'</div>'+
(open?'<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px">'+
(canRemove?'<button class="admin-btn" onclick="reportAction(\''+_escR(r.id)+'\',\'remove\')" style="font-size:12px;padding:7px 14px;color:#f87171;border:1px solid rgba(248,113,113,.4)">🗑 Remove '+_escR((_RP_TYPE[r.target_type]||'').toLowerCase())+'</button>':'')+'<button class="admin-btn" onclick="reportAction(\''+_escR(r.id)+'\',\'dismiss\')" style="font-size:12px;padding:7px 14px">✓ Dismiss — nothing wrong</button>'+'<button class="admin-btn" onclick="reportAction(\''+_escR(r.id)+'\',\'done\')" style="font-size:12px;padding:7px 14px;background:rgba(168,255,0,.12);color:#A8FF00;border:1px solid rgba(168,255,0,.35)">Mark as done</button>'+
(t.author_id&&!t.author_banned?'<button class="admin-btn" onclick="reportBanAuthor(\''+_escR(r.id)+'\')" style="font-size:12px;padding:7px 14px;color:#f87171">⛔ Ban '+_escR((t.author_name||'member').split(' ')[0])+'</button>':'')+'</div>':'<div style="margin-top:12px;font-size:12px"><span style="color:'+res[1]+';font-weight:700">'+res[0]+'</span>'+'<span style="color:#666"> · '+_rpWhen(r.resolved_at)+(r.resolved_by_name?' by '+_escR(r.resolved_by_name):'')+'</span>'+
(r.resolution_note?'<div style="color:#aaa;margin-top:4px">Note: '+_escR(r.resolution_note)+'</div>':'')+'</div>')+'</div>';}).join('');host.innerHTML=html;if(_rpState.focus){var el=document.getElementById('rp-'+_rpState.focus);_rpState.focus=null;if(el){el.scrollIntoView({behavior:'smooth',block:'center'});el.style.borderColor='#A8FF00';setTimeout(function(){el.style.borderColor='#1f1f1f';},2500);}}}
function _rpToast(msg,ok){if(typeof showToast==='function'){showToast(msg,!ok);return;}
alert(msg);}
function _rpPost(id,body){return fetch(ATP_API+'/admin/reports/'+encodeURIComponent(id)+'/action',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+getToken()},body:JSON.stringify(body),}).then(function(r){return r.json().then(function(j){if(!r.ok)throw new Error(j.error||('HTTP '+r.status));return j;});});}
function reportAction(id,action){var r=_rpState.rows.find(function(x){return x.id===id;})||{};var what=(_RP_TYPE[r.target_type]||'item').toLowerCase();var note=null;if(action==='remove'){if(!window.confirm('Remove this '+what+' from the community? Members will no longer see it.'))return;note=window.prompt('Optional note (admins only):','');if(note===null)return;}else if(action==='dismiss'){note=window.prompt('Dismiss — nothing wrong with this '+what+'. Optional note (admins only):','');if(note===null)return;}else{note=window.prompt('What was done? (e.g. "Spoke to the member") — admins only:','');if(note===null)return;}
_rpPost(id,{action:action,note:note||null}).then(function(d){var label=action==='remove'?'Removed':action==='dismiss'?'Dismissed':'Marked as done';_rpToast(label+(d.closed>1?' · '+d.closed+' reports closed':''),true);loadReportsSection();}).catch(function(e){_rpToast('Failed: '+(e.message||e),false);});}
function reportBanAuthor(id){var r=_rpState.rows.find(function(x){return x.id===id;});if(!r||!r.target||!r.target.author_id)return;var name=r.target.author_name||'this member';var reason=window.prompt('Ban '+name+'? They will be signed out and blocked from ATP (they can appeal).\nReason (shown in the admin record):','Reported: '+(r.reason||''));if(reason===null)return;fetch(ATP_API+'/admin/members/'+encodeURIComponent(r.target.author_id)+'/ban',{method:'PATCH',headers:{'Content-Type':'application/json',Authorization:'Bearer '+getToken()},body:JSON.stringify({banned:true,reason:reason||null}),}).then(function(res){return res.json().then(function(j){if(!res.ok)throw new Error(j.error||('HTTP '+res.status));return j;});}).then(function(){return _rpPost(id,{action:'done',note:'Author banned'+(reason?': '+reason:'')});}).then(function(){_rpToast(name+' banned · report closed',true);loadReportsSection();}).catch(function(e){_rpToast('Ban failed: '+(e.message||e),false);});}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',refreshReportsBadge);else refreshReportsBadge();